class Tenant(models.Model):
    slug = models.SlugField(unique=True)
    name = models.CharField(max_length=160)
    region = models.CharField(max_length=20, default="eu")
    plan = models.ForeignKey("billing.Plan", on_delete=models.PROTECT)

class Membership(models.Model):
    tenant = models.ForeignKey(Tenant, on_delete=models.CASCADE)
    user = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE)
    role = models.CharField(max_length=20)
    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["tenant", "user"], name="unique_tenant_user")
        ]

class TenantOwnedModel(models.Model):
    tenant = models.ForeignKey(Tenant, on_delete=models.CASCADE)
    class Meta:
        abstract = True

class UsageCounter(models.Model):
    tenant = models.ForeignKey(Tenant, on_delete=models.CASCADE)
    meter = models.CharField(max_length=40)
    period = models.DateField()
    value = models.BigIntegerField(default=0)
    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["tenant", "meter", "period"],
                name="unique_tenant_meter_period",
            )
        ]

