def require_tenant(view):
    @wraps(view)
    def wrapped(request, *args, **kwargs):
        memberships = Membership.objects.filter(user=request.user).select_related("tenant")
        tenant_id = request.session.get("tenant_id")
        membership = memberships.filter(tenant_id=tenant_id).first()
        if membership is None:
            membership = memberships.order_by("tenant_id").first()
        if membership is None:
            raise PermissionDenied("No active workspace")
        request.tenant = membership.tenant
        request.membership = membership
        return view(request, *args, **kwargs)
    return wrapped

@require_tenant
def invoice_list(request):
    invoices = Invoice.objects.for_tenant(request.tenant).order_by("-created_at")
    return render(request, "billing/list.html", {"invoices": invoices})

@csrf_exempt
@require_POST
def provider_webhook(request, provider):
    raw = request.body
    if not verify_signature(provider, raw, request.headers):
        return HttpResponse(status=401)

    payload = json.loads(raw)
    with transaction.atomic():
        event, created = InboundEvent.objects.get_or_create(
            provider=provider,
            event_id=payload["id"],
            defaults={
                "event_type": payload["type"],
                "payload_hash": sha256(raw).hexdigest(),
            },
        )
        if created:
            EventOutbox.objects.create(
                topic=f"webhook.{provider}",
                payload={"event_id": event.pk},
            )
    return HttpResponse(status=200)

