def resolve_implementation(capability, request):
    flag = CutoverDecision.objects.filter(
        capability=capability,
        cohort=request.cohort,
        enabled=True,
    ).exists()
    if not flag:
        return legacy_handler(capability, request)

    try:
        return new_handler(capability, request)
    except Exception:
        logger.exception("new capability failed", extra={"capability": capability.key})
        metrics.increment("cutover.fallback", tags={"capability": capability.key})
        return legacy_handler(capability, request)
